	//        "orderId": "1234",                       // ccxt.Order Id
	//        "origQty": "34244",                      // Original Quantity
	//        "avgPrice": "123",                       // Quantity
	//        "price": "1111",                         // Average price
	//        "executedQty": "34244",                  // Volume (Cont)
	//        "orderSide": "BUY",                      // BUY, SELL
	//        "positionSide": "LONG",                  // LONG, SHORT
